#!/usr/bin/env node
import {
  convertCircuitJsonToTscircuit
} from "../chunk-35I53U4L.js";

// cli/main.ts
import { Command } from "commander";
import { readFile, writeFile } from "fs/promises";

// package.json
var package_default = {
  name: "circuit-json-to-tscircuit",
  main: "dist/lib/index.js",
  exports: {
    ".": "./dist/lib/index.js",
    "./cli": "./dist/cli/main.js"
  },
  type: "module",
  version: "0.0.77",
  repository: {
    type: "git",
    url: "https://github.com/tscircuit/circuit-json-to-tscircuit.git"
  },
  scripts: {
    build: "tsup-node lib/index.ts cli/main.ts --format esm --dts",
    "build:site": "bun build ./site/index.html --outdir site-build",
    "dev:site": "bun --hot ./site/index.html",
    test: "bun test",
    format: "biome format --write .",
    "format:check": "biome format ."
  },
  devDependencies: {
    "@biomejs/biome": "^1.9.4",
    "@tscircuit/mm": "^0.0.8",
    "@tscircuit/soup-util": "^0.0.41",
    "@types/bun": "latest",
    "@types/react": "18",
    "@types/react-dom": "18",
    "bun-match-svg": "^0.0.15",
    "circuit-json": "^0.0.507",
    "circuit-to-svg": "^0.0.353",
    commander: "^13.1.0",
    prettier: "^3.9.5",
    "schematic-symbols": "0.0.248",
    shiki: "^4.3.1",
    "stack-svgs": "^0.0.1",
    "transformation-matrix": "3.1.0",
    tscircuit: "0.0.2703-libonly",
    tsup: "^8.3.5",
    zod: "^3.25.76"
  },
  peerDependencies: {
    typescript: "^5.0.0"
  }
};

// cli/main.ts
var program = new Command();
program.name("circuit-json-to-tscircuit").description("Convert circuit.json files to TSCircuit components").version(package_default.version).argument("<input>", "Input circuit.json file path").option("-o, --output <path>", "Output TSX file path").option("-n, --name <name>", "Component name").action(async (input, options) => {
  if (!options.output) {
    throw new Error("Output path is required. Use -o or --output option.");
  }
  console.log(`Converting ${input} to ${options.output}`);
  console.log("Reading input file...");
  const jsonContent = await readFile(input, "utf-8");
  console.log("Parsing JSON...");
  const circuitJson = JSON.parse(jsonContent);
  if (!Array.isArray(circuitJson)) {
    throw new Error(
      "Invalid circuit.json: expected an array of circuit elements"
    );
  }
  console.log("Converting to TSCircuit...");
  const tsxContent = convertCircuitJsonToTscircuit(circuitJson, {
    componentName: options.name || "Circuit"
  });
  console.log("TSX content generated");
  console.log("Writing output file...");
  await writeFile(options.output, tsxContent, "utf-8");
  console.log("Conversion completed successfully!");
});
if (process.argv.length === 2) {
  program.help();
} else {
  program.parse();
}
